package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class LocaleUtils_toLocale_TriageGen2Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_ValidLanguageOnly() {
        Locale result = LocaleUtils.toLocale("en");
        assertEquals(new Locale("en", ""), result);
    }

    @Test
    public void testToLocale_ValidLanguageAndCountry() {
        Locale result = LocaleUtils.toLocale("en_US");
        assertEquals(new Locale("en", "US"), result);
    }

    @Test
    public void testToLocale_ValidLanguageAndCountryAndVariant() {
        Locale result = LocaleUtils.toLocale("en_US_POSIX");
        assertEquals(new Locale("en", "US", "POSIX"), result);
    }

    @Test
    public void testToLocale_InvalidLength_TooShort() {
        try {
            LocaleUtils.toLocale("e");
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: e", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidLength_Not2Not5Not7Plus() {
        // len 3 or 4 or 6 are not allowed by the logic (len != 2 && len != 5 && len < 7)
        // Actually, the condition is (len != 2 && len != 5 && len < 7)
        // If len is 3: (3!=2 [T] && 3!=5 [T] && 3<7 [T]) -> Throws
        // If len is 6: (6!=2 [T] && 6!=5 [T] && 6<7 [T]) -> Throws
        try {
            LocaleUtils.toLocale("en_U"); // len 4
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_U", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidLanguageChars() {
        try {
            LocaleUtils.toLocale("E1"); // Uppercase or digit
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: E1", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidCountrySeparator() {
        try {
            LocaleUtils.toLocale("en-US"); // Should be underscore
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en-US", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidCountryChars() {
        try {
            LocaleUtils.toLocale("en_uS"); // Lowercase country
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_uS", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidVariantSeparator() {
        try {
            LocaleUtils.toLocale("en_US-POSIX"); // Should be underscore
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US-POSIX", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidLength_ExactlySix() {
        // len 6: (6!=2 [T] && 6!=5 [T] && 6<7 [T]) -> Throws
        try {
            LocaleUtils.toLocale("en_US_");
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US_", e.getMessage());
        }
    }
}
